  /**
   * Returns the path mirrored for the red alliance if needed. Call during autonomousInit() or later
   * when the alliance is known.
   */
  public static PathData forAlliance(PathData path) {
    var alliance = MatchState.getAlliance();
    if (alliance.isPresent() && alliance.get() == Alliance.RED) {
      return path.mirrorForRedAlliance();
    }
    return path;
  }

  /** Returns the constant name for a path declared in this class. */
  public static String nameOf(PathData path) {
    for (Field field : Paths.class.getDeclaredFields()) {
      if (field.getType() != PathData.class
          || !Modifier.isStatic(field.getModifiers())
          || !Modifier.isPublic(field.getModifiers())) {
        continue;
      }

      try {
        if (field.get(null) == path) {
          return field.getName();
        }
      } catch (IllegalAccessException e) {
        throw new IllegalStateException("Unable to read path constant: " + field.getName(), e);
      }
    }

    throw new IllegalArgumentException("Path is not a named constant in Paths");
  }
